import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';
import arkenv from '@arkenv/vite-plugin';

export default defineConfig({
  plugins: [
    react(),
    arkenv({
      VITE_API_URL: 'string.url',
      VITE_FEATURE_FLAGS: 'boolean',
      VITE_MAX_UPLOAD_MB: '1 <= number.integer <= 1024',
    }),
  ],
});

import React from 'react';
import ReactDOM from 'react-dom/client';

const apiUrl = import.meta.env.VITE_API_URL;

function App() {
  return (
    <div>
      <h1>ArkEnv Vite Plugin Build Gate</h1>
      <p>API URL: <span id="api-url">{apiUrl}</span></p>
    </div>
  );
}

ReactDOM.createRoot(document.getElementById('root')!).render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

/// <reference types="vite/client" />

interface ImportMetaEnv {
  readonly VITE_API_URL: string;
  readonly VITE_FEATURE_FLAGS: boolean;
  readonly VITE_MAX_UPLOAD_MB: number;
}

interface ImportMeta {
  readonly env: ImportMetaEnv;
}
